import numpy as np, torch, model
net = model.load(); neg = model.negatives()
mem=[1,3,12]
torch.manual_seed(1)
xi=torch.randn(4000,2)
def dec(c):
    a=model.decode(net,xi,torch.full((len(xi),),float(c)))
    return np.asarray(a[0] if isinstance(a,tuple) else a)
ref={}
for i in mem:
    a=dec(neg['c'][i]); ref[i]=model.in_basin(i,a)
    print(i, ref[i].mean(), 'xi mean ang', np.degrees(np.arctan2(*xi.numpy()[ref[i]].mean(0)[::-1])), 'xi |mean|', np.linalg.norm(xi.numpy()[ref[i]].mean(0)))
R=ref[1]|ref[3]|ref[12]
for c in np.linspace(0.05,0.95,10):
    a=dec(c); bad=np.zeros(len(a),bool)
    for i in mem: bad|=model.in_basin(i,a)
    ang=np.degrees(np.arctan2(a[R,1],a[R,0]))
    print(round(c,2),'bad',round(bad.mean(),3),'P(bad|R)',round(bad[R].mean(),2),'P(bad|notR)',round(bad[~R].mean(),3),'R angle med',round(np.median(ang),1),'rad',round(np.median(np.linalg.norm(a[R],axis=1)),2))

